":5,"skills":[{"name":"use-cases","path":"skills/use-cases/SKILL.md","description":"Use when planning, updating, verifying, or recovering the freshness of product behaviours bound to code \u2014 the keyless daily loop (bind -> verify -> local \u2713 -> recover), plus behaviour inventory, matrix health, and safe evidence records in a workspace.","complete":true},{"name":"showcase","path":"skills/showcase/SKILL.md","description":"Use when preparing or performing a live user-visible showcase, demo, sign-off flow, pre-merge acceptance run, or high-value feature proof from use cases and evidence.","complete":true},{"name":"walkthrough","path":"skills/walkthrough/SKILL.md","description":"Use when producing an extensive product or feature walkthrough with use cases, caveats, gaps, edge or failure cases, evidence provenance, and non-live presentation structure.","complete":true},{"name":"init","path":"skills/init/SKILL.md","description":"Use once in a repo that has decided to be use-case driven \u2014 runs use-cases init to scaffold the matrix, record the decision in AGENTS.md, vend a sample row and wire the git hooks, then hands straight over to the use-case-driven-development loop.","complete":true},{"name":"use-case-driven-development","path":"skills/use-case-driven-development/SKILL.md","description":"Use at the start of framing on every piece of work \u2014 to read the once-per-repo decision \"use-case driven development for this repo?\" recorded in its AGENTS.md \u2014 and, on a yes, at every phase that has a use-case touch. The matrix is the entry point between what the user wants and the code, rows are agreed before tests, tests and code are wrapped in the row's markers, any issue starts in the matrix, and the scan is the coverage number. A no changes nothing else. The use-cases commands themselves are in the use-cases skill.","complete":true}],"host_registration":{"complete":true,"hosts":[{"host":"claude","manifest_path":".claude-plugin/plugin.json","declares_skill